*************************Crosswalk between applications and granted patents********************************

*pg_granted_pgpubs_crosswalk.tsv downloaded from USPTO 7/31/2023
import delimited "pg_granted_pgpubs_crosswalk.tsv", encoding(ISO-8859-1) clear stringcols(1)

//drop if missing patent number
drop if patent_id==""

//drop if noncurrent patent number
drop if current_patent_id_flag=="FALSE"

******************************Generate house judiciary committee seniority at city level to be merged with applicant-city********************************
//source: https://github.com/OpenSourceActivismTech/us-zipcodes-congress
//Districts in single district states have the district coded as "0". Renumber these districts to "1" to merge with the Stewart data. States: AK, DE, ND, SD, VT, MT, and WY.//
use "zip district github.dta",clear //downloaded 1/3/2021
replace cd=1 if cd==0
save "zip district github correct.dta",replace
